    /**
     * Gets or sets the related beat tick lookup.
     */
    public var beatLookup: BeatTickLookup!

    /**
     * Gets or sets the beat that will be played next.
     */
    public var nextBeat: MidiTickLookupFindBeatResult? = nil

    /**
     * Gets or sets the duration in midi ticks how long this lookup is valid.
     */
    public var tickDuration: Double = 0.0

    /**
     * Gets or sets the duration in milliseconds how long this lookup is valid.
     */
    public var duration: Double = 0.0

    /**
     * The mode how the cursor should be handled.
     */
    public var cursorMode: MidiTickLookupFindBeatResultCursorMode = MidiTickLookupFindBeatResultCursorMode.Unknown

    public var start: Double {
        get {
            return self.masterBar.start + self.beatLookup.start
        }
    }

    public var end: Double {
        get {
            return self.start + self.tickDuration
        }
    }

    public init(_ masterBar: MasterBarTickLookup) {
        self.masterBar = masterBar
    }

    public func calculateDuration() {
        if self.masterBar.tempoChanges.length == 1.0 {
            self.duration = MidiUtils.ticksToMillis(self.tickDuration, self.masterBar.tempoChanges[0].tempo)
        } else {
            var millis: Double = 0.0
            var currentTick: Double = self.start
            var currentTempo: Double = self.masterBar.tempoChanges[0].tempo
            let endTick: Double = self.end
            for change in self.masterBar.tempoChanges {
                if change.tick < currentTick {
                    currentTempo = change.tempo
                } else if change.tick > endTick {
                    break
                } else {
                    millis += MidiUtils.ticksToMillis(change.tick - currentTick, currentTempo)
                    currentTempo = change.tempo
                    currentTick = change.tick
                }
            }
            if endTick > currentTick {
                millis += MidiUtils.ticksToMillis(endTick - currentTick, currentTempo)
            }
            self.duration = millis
        }
    }
